// ---- Name colour codes (spec/pes_savefile/model.md "Name colour codes") ----
// \x11c + 8 hex digits (RRGGBBAA) colours the text after it; \x11d resets.
// The name field keeps the raw string; the list and headings render the codes.
const CODE_RE = /\x11c([0-9a-fA-F]{8})|\x11d/g;
function displayName(raw) { return raw.replace(CODE_RE, ""); }
// A name's runs of text, each with its colour code's colour (null: none).
function nameRuns(raw) {
  const runs = []; let color = null, i = 0, m;
  CODE_RE.lastIndex = 0;
  while ((m = CODE_RE.exec(raw))) {
    if (m.index > i) runs.push([raw.slice(i, m.index), color]);
    color = m[1] ? "#" + m[1].slice(0, 6) : null;
    i = m.index + m[0].length;
  }
  if (i < raw.length) runs.push([raw.slice(i), color]);
  return runs;
}
