// where nobody is stripped is an ordinary unstripped save (no list).
function restoredIds() {
  const all = curSave().teams.flatMap(t => t.players);
  if (!all.some(isStripped)) return [];
  return all.filter(p => p.appearance_id > 0);
}
// Opening another save with unsaved changes prompts first (SE-GUI-05); the
// window-close half of the prompt is the shell's (index.html).
function requestOpen(key, path) {
  if (dirty()) { drawUnsavedPrompt(() => openSave(key, path)); return; }
  openSave(key, path); render();
}
// Edits: one undo entry is a list of (object-path, before, after) patches plus
// the touched player keys. Reorder pushes a team's slot order, not a field.
function edit(label, fn) {
  const before = snapshot();
  fn();
  S.undo.push({ label, before, after: snapshot() });
  S.redo = [];
  // The list of changes is computed when it opens: an edit under it (a
  // shortcut's, the pointer's click already closed it) closes it rather
  // than leaving a stale list.
  S.changesPop = false;
}
function snapshot() { return JSON.stringify(S.save.teams); }
function restore(snap) { S.save.teams = JSON.parse(snap); }
// Undo/redo re-render like the real view's frame: the snapshot restore swaps
// the whole teams array, so a widget drawn before it would write into a dead
// object.
function doUndo() {
  const e = S.undo.pop(); if (!e) return;
  const cur = snapshot(); restore(e.before);
  S.redo.push({ label: e.label, before: e.before, after: cur });
  S.changesPop = false;
  render();
}
function doRedo() {
  const e = S.redo.pop(); if (!e) return;
  const cur = snapshot(); restore(e.after);
  S.undo.push({ label: e.label, before: cur, after: e.after });
  S.changesPop = false;
  render();
}
// Unsaved changes = the model differs from the opened/last-saved bytes (the
// dot's test too: a player is dirty while his entry differs).
const dirty = () => JSON.stringify(S.save.teams) !== S.baseline;
function dirtyPlayer(p) {
  return S.basePlayers[teamOf(p).id + ":" + p.slot] !== JSON.stringify(p);
}
// The team's own fields (never its players) differ from the opened or last
// saved state: the team row's dot.
function dirtyTeam(t) {
  return S.baseTeams[t.id] !== JSON.stringify({ ...t, players: undefined });
}
function teamOf(p) { return curSave().teams.find(t => t.players.includes(p)); }

// ---- Save and Save as (SE-GUI-03, 21, 26) ----
// While the save's own game runs, Save first says how to keep the write: the
// game writes its own copy over the file when the member leaves Edit mode
// after changing anything there, so an open Edit mode needs its Data
// Management > Load before leaving, and a closed one reads the file when
// opened. Save writes and the pending action goes on; Cancel writes nothing.
// Another version's game asks nothing.
// sample wording: the dialog's text and the status lines.
function dlgGameRunning(then) {
  dlg("game-running", "PES 20" + version() + " is running", h("div", {},
    h("p", {}, "If the game's Edit mode is open, use its Data Management > Load after saving, "
      + "before you leave Edit mode: leaving it after changing anything there writes the "
      + "game's own copy over this save."),
    h("p", {}, "If Edit mode is closed, the changes show when you open it.")),
    [button("Cancel", closeWindow),
     button("Save", () => { closeWindow(); writeSave(S.path); if (then) then(); render(); })]);
}
function saveFile(then) {
  if (D.gameRunning) return dlgGameRunning(then);
  writeSave(S.path);
  if (then) then();
}
function writeSave(path) {
  S.path = path;
  S.baseline = JSON.stringify(S.save.teams);
  S.basePlayers = {};
  S.baseTeams = {};
  for (const t of S.save.teams) {
    for (const p of t.players) S.basePlayers[t.id + ":" + p.slot] = JSON.stringify(p);
    S.baseTeams[t.id] = JSON.stringify({ ...t, players: undefined });
  }
  publishNotice("Saved " + path.split("\\").pop() + " (the replaced file is kept once as " + path.split("\\").pop() + ".bak)", null, "success");
  pushRecent(path);
}
function saveAs() {
  const input = h("input", { type: "text", style: "width:420px", value: S.path });
  dlg("save-as", "Save as", h("div", {},
    h("p", {}, weak("The native file picker (rfd) opens here; the draft edits the path inline.")),
    input),
    [button("Save", () => { closeWindow(); writeSave(input.value); render(); }),
     button("Cancel", closeWindow)]);
}

// ---- The prompts and notices ----
// SE-GUI-05: save, discard or cancel before another save opens, over the list
// of what would be saved or lost: one row per changed field against the file as
// opened or last saved (the dots' baseline), players then teams' own fields.
// The real view words a row in the fields' terms (the Comparator panel's rule);
// the draft's labels are the model's keys title-cased and its values stored.
// sample wording: the prompt's text and the column heads.
function flatDiff(a, b, path, out) {
  if (a !== null && b !== null && typeof a === "object" && typeof b === "object") {
    for (const k of new Set([...Object.keys(a), ...Object.keys(b)]))
      flatDiff(a[k], b[k], path.concat(k), out);
  } else if (JSON.stringify(a) !== JSON.stringify(b)) {
    out.push([path, a, b]);
  }
}
// The view's label where it is not the key's title case (the real view
// words every row from its terms; the draft words the few its renders show).
const CHANGE_LABELS = { fluid: "Fluid formation" };
function changeLabel(path) {
  const named = path.filter(k => !/^\d+$/.test(k));
  const index = path.filter(k => /^\d+$/.test(k)).map(k => Number(k) + 1);
  const key = named[named.length - 1] || "";
  // A preset's field names its preset as the Tactics bar does; any other
  // indexed field keeps its 1-based index after the label.
  if (named.includes("presets")) return "Preset " + index[0] + " · " + (CHANGE_LABELS[key] || titleCase(key));
  return titleCase(key) + (index.length ? " " + index.join(".") : "");
}
function unsavedChanges() {
  const base = JSON.parse(S.baseline);
  const rows = [];
  for (const t of S.save.teams) {
    const bt = base.find(x => x.id === t.id);
    if (!bt) continue;
    for (const p of t.players) {
      const bp = bt.players.find(x => x.id === p.id);
      if (!bp) continue;
      const out = []; flatDiff(bp, p, [], out);
      for (const [path, o, n] of out)
        rows.push([displayName(p.name) + " · " + changeLabel(path), o, n]);
    }
  }
  for (const t of S.save.teams) {
    const bt = base.find(x => x.id === t.id);
    if (!bt) continue;
    // A colour is one row with the hex the team view shows, not a row per
    // stored channel.
    const skip = { players: undefined, color_1: undefined, color_2: undefined };
    for (const [key, label] of [["color_1", "Colour 1"], ["color_2", "Colour 2"]])
      if (shownHex(bt[key]) !== shownHex(t[key]))
        rows.push([t.name + " · " + label, shownHex(bt[key]).toUpperCase(), shownHex(t[key]).toUpperCase()]);
    const out = [];
    flatDiff({ ...bt, ...skip }, { ...t, ...skip }, [], out);
    for (const [path, o, n] of out) rows.push([t.name + " · " + changeLabel(path), o, n]);
  }
  return rows;
}
// The table of unsaved changes, the close prompt's and the toolbar label's
// popup's alike: one row per changed field, a checkbox read as on or off,
// scrolling past 240 points.
function changesTable() {
  const show = v => v === undefined || v === null ? "" : typeof v === "boolean" ? (v ? "on" : "off")
    : typeof v === "object" ? JSON.stringify(v) : String(v);
  // A colour's value draws its swatch before the hex (the app's rows carry the
  // colour itself; the draft reads it back from the hex).
  const cell = v => { const s = show(v);
    return h("td", { class: "mono" }, /^#[0-9A-F]{6}$/i.test(s)
      ? h("span", { class: "chswatch", style: "background:" + s }) : null, s); };
  const changes = h("table", { class: "grid", id: "unsaved-changes" },
    h("tr", {}, h("th", {}, "Item"), h("th", {}, "Old value"), h("th", {}, "New value")),
    unsavedChanges().map(([item, o, n]) => h("tr", {}, h("td", {}, item), cell(o), cell(n))));
  return h("div", { style: "max-height:240px; overflow:auto" }, changes);
}
function drawUnsavedPrompt(then) {
  window_("Unsaved changes", h("div", {},
    changesTable()),
    [button("Save", () => { closeWindow(); saveFile(then); render(); }),
     button("Discard", () => { closeWindow(); then(); render(); }),
     button("Cancel", closeWindow)], "unsaved-changes");
}
// SE-GUI-20: opening a Fox save whose ids are set while others are stripped
// lists them with a one-click Strip again (ids to -1, one undoable edit).
// sample wording: the window's text.
function drawStripAgain(list) {
  const rows = list.map(p => {
    const t = teamOf(p);
    return h("div", { class: "row" }, h("span", { class: "mono weak" }, t.name),
      " ", h("span", { class: "mono weak" }, String(p.slot).padStart(2, "0")), " ",
      h("span", {}, ...nameSpans(p.name)));
  });
  window_("Appearance ids set on a stripped save", h("div", {},
    h("p", {}, list.length + (list.length === 1 ? " player has" : " players have")
      + " an appearance id set while the rest are stripped:"),
    h("div", { class: "mono", style: "max-height:200px; overflow:auto" }, rows)),
    [button("Strip again", () => {
      edit("Strip again", () => { for (const p of list) p.appearance_id = -1; });
      closeWindow(); render();
    }), button("Close", closeWindow)]);
}
// The open-save flow calls window_ directly; after the modal closes render()
// must still run for the state change openSave made.

// ---- Quick actions (SE-GUI-09) ----
// The fake of aatf::apply_tier: the rating stats go to the tier's rate, its
// stats map overrides them, and form / injury resistance / weak foot take the
// tier's game numbers (stored one lower). name_color rewrites the name's
// leading code; a tier that sets none removes a leading code this ruleset's
// tiers use and keeps any other. One undoable edit.
function applyTier(p, tier) {
  edit("Make " + tier.label, () => {
    for (const s of RATING_STATS)
      if (p.stats[s] !== undefined) p.stats[s] = tier.rate;
    for (const [k, v] of Object.entries(tier.stats || {}))
      if (p.stats[k] !== undefined) p.stats[k] = v;
    p.stats.form = tier.form - 1;
    p.stats.injury_resistance = tier.injury_resistance - 1;
    p.stats.weak_foot_usage = tier.weak_foot.usage - 1;
    p.stats.weak_foot_accuracy = tier.weak_foot.accuracy - 1;
    const lead = p.name.match(/^\x11c[0-9a-fA-F]{8}/);
    const colors = new Set(RULESETS[D.ruleset].tiers.map(t => t.name_color).filter(Boolean));
    if (tier.name_color)
      p.name = "\x11c" + tier.name_color + (lead ? p.name.slice(lead[0].length) : p.name);
    else if (lead && colors.has(lead[0].slice(2)))
      p.name = p.name.slice(lead[0].length);
  });
}
function setAllStats(p, n) {
  edit("Set stats " + n, () => {
    for (const s of ABILITY_STATS) if (p.stats[s] !== undefined) p.stats[s] = n;
  });
}
// A small field write helper: every control's change is one undoable edit.
function set(p, get, put, v, label) {
  if (get(p) === v) return;
  edit(label || "edit", () => put(p, v));
}
// Drag to reorder (SE-GUI-08): the records move, the roster does not. Slot NN
// keeps player id `team id × 100 + NN` (plans/aatf_rules.md "The host"), its
// base_copy_id and its shirt number, and the captain stays with his slot; the
// dragged player's record lands on the target slot's id and the records in
// between shift one slot along, as 4ccEditor's spinner trades two records per
// step. Its exported record has no face structure or hairstyle, so each slot
// also keeps its appearance's face and hair (skin, iris and gloves move).
const SLOT_KEEPS = ["slot", "id", "base_copy_id", "number"];
function movePlayer(team, fromSlot, toSlot) {
  if (fromSlot === toSlot) return;
  edit("Reorder", () => {
    const arr = team.players;
    const i = arr.findIndex(p => p.slot === fromSlot);
    const j = arr.findIndex(p => p.slot === toSlot);
    const records = arr.map(p => Object.fromEntries(
      Object.entries(p).filter(([k]) => !SLOT_KEEPS.includes(k))));
    const looks = arr.map(p => p.appearance && { face: p.appearance.face, hair: p.appearance.hair });
    const [m] = records.splice(i, 1);
    records.splice(j, 0, m);
    arr.forEach((p, k) => {
      for (const key of Object.keys(p)) if (!SLOT_KEEPS.includes(key)) delete p[key];
      Object.assign(p, records[k]);
      if (p.appearance && looks[k]) p.appearance = { ...p.appearance, ...looks[k] };
    });
  });
  // The selection follows the dragged player, now on the target slot.
  S.sel = { team: team.id, slot: toSlot };
}

// ---- Draft controls: the scenarios' GIVENs, visibly outside Studio ----
function draftControls() {
  const grp = label => h("span", { class: "weak dcgroup" }, label);
  return [
    h("label", { class: "cb" }, "Open save",
      combo([["pes17", "PES 17 sample (the maintainer's save)"],
        ["pes21", "PES 21 sample"]], S.saveKey || D.sample,
        v => { D.sample = v; requestOpen(v); })),
    h("label", { class: "cb", title: "SE-GUI-28" }, "PES selector",
      combo(PES_VERSIONS.map(v => [v, "PES " + v]), D.selectorVersion,
        v => D.selectorVersion = v)),
    h("span", { title: "SE-GUI-21" }, cb("The save's game is running", D.gameRunning,
      v => D.gameRunning = v)),
    h("span", { title: "The Tactics pitch's portraits" }, cb("The game's download folder has portraits",
      D.portraits, v => { D.portraits = v; render(); })),
    h("label", { class: "cb", title: "SE-GUI-20" }, "Appearance ids (PES 21)",
      combo([["all_set", "every player's set (the real save)"],
        ["mixed", "stripped, three restored"],
        ["stripped", "all stripped"]], D.appearanceIds,
        v => { D.appearanceIds = v; if (S.save && version() >= 19) requestOpen("pes21"); })),
    h("span", { title: "SE-GUI-35: the settings menu's checkbox (the draft has no settings menu); on when the cup's looks are compiled from exports: the save's aesthetics are then read-only, behind Edit aesthetics anyway in the Appearance section" },
      cb("Aesthetics from exports", D.aesFromExports, v => { D.aesFromExports = v; render(); })),
    h("span", { title: "SE-GUI-30: the draft recomputes player rows only; off drops the team's rows so the empty state can be reached" },
      cb("Live AATF keeps the sample's team rows", D.liveTeamRows, v => D.liveTeamRows = v)),
    h("span", { title: "the picker's host-supplied swatches; the Save editor passes none" },
      cb("Picker suggestions, as a kit editor would pass", D.pickerSugg,
        v => D.pickerSugg = v)),
    h("span", { title: "8.33 and 8.34: the draft writes no file; this shows the last picture a save or a range run drew" },
      button("Last picture written", dlgLastPicture, { disabled: !S.lastPicture })),
    collapsing("save-editor/walk", "How to walk the scenarios", () => WALK.map(([id, how]) =>
      h("div", {}, strong(id), " ", how))),
    collapsing("v2remarks", "Arrangement v2: the collaborator's remarks",
      () => V2_REMARKS.map(r => h("div", {}, r)))];
}
