// ---- The Save editor's view (the central panel) ----
// The Open menu (SE-GUI-26): the discovered saves labelled by version (and
// account folder for 19+), the session's recent files, then the picker.
// sample wording: the menu's labels and the picker's entry.
function openMenu() {
  const items = DISCOVERED.map(d => {
    const label = "PES " + d.version + (d.account ? " (" + d.account + ")" : "");
    const key = d.version === "2017" ? "pes17" : d.version === "2021" ? "pes21" : null;
    return [label, () => key ? requestOpen(key, d.path)
      : dlgOpenSave(d), false, d.path];
  });
  items.push("-");
  for (const path of S.recents) {
    const key = Object.entries(SAMPLE_PATH).find(([, p]) => p === path)?.[0];
    items.push([path.split("\\").slice(-3).join("\\"), () =>
      key ? requestOpen(key, path) : closeWindow(), false, path]);
  }
  items.push("-");
  items.push(["Choose file\u2026", dlgChooseFile, false,
    "Opens in the selected version's save folder when it exists"]);
  return menu("Open", items);
}

// The toolbar: file actions and undo/redo (Ctrl+S also works), the open
// save's path and the unsaved-changes marker. sample wording: the marker and
// the buttons' tooltips.
function renderToolbar() {
  const undoBtn = button("Undo", () => { doUndo(); render(); },
    { disabled: !S.undo.length, title: S.undo.length ? "Undo: " + S.undo[S.undo.length - 1].label : "Nothing to undo" });
  undoBtn.id = "undo-btn";
  const redoBtn = button("Redo", () => { doRedo(); render(); },
    { disabled: !S.redo.length, title: S.redo.length ? "Redo: " + S.redo[S.redo.length - 1].label : "Nothing to redo" });
  redoBtn.id = "redo-btn";
  const saveBtn = button("Save", () => { saveFile(); render(); }, { title: "Ctrl+S" });
  saveBtn.id = "save-btn";
  // The file's buttons, then Undo and Redo, then the menus, each group after a
  // separator, and one more before the ruleset picker and Live AATF.
  const tsep = () => h("span", { class: "tsep" });
  return h("div", { class: "toolbar", "data-panel": "toolbar" },
    openMenu(), saveBtn, button("Save as", saveAs), tsep(),
    undoBtn, redoBtn, tsep(),
    playerMenu(), teamMenu(), databaseMenu(), tsep(),
    rulesetPicker(), liveButton(), LIVE.on ? suggestionsToggle() : null,
    // The save's path is in the window title (`titleDetail`): beside the
    // unsaved mark it could wrap the toolbar onto a second row.
    dirty() ? unsavedLabel() : null);
}
// The unsaved-changes label (a Label with Sense::click; the pointing-hand
// cursor and a tooltip say it opens something) and, while open, its popup
// under it: the close prompt's table without its answers, computed when it
// opens as the prompt's is. Closed by a click outside, Esc, the label again
// or an edit; the toolbar's Undo is a click outside, so it closes the list
// and the label reopens it one row shorter. Not a window: a glance at what
// Save would write, not a workspace to keep open.
// sample wording: the tooltip.
function unsavedLabel() {
  return h("span", { class: "chfield" },
    h("span", { class: "unsaved", id: "unsaved-label",
      title: "Lists the changes since the save was opened or last saved",
      onclick: () => { S.changesPop = !S.changesPop; render(); } }, "• unsaved changes"),
    S.changesPop ? changesPopup() : null);
}
function changesPopup() {
  const pop = h("div", { class: "chpop", id: "changes-popup" }, changesTable());
  // Measured once drawn: the label sits late in the toolbar, so a wide
  // table under it can pass the window's edge (egui's Area is constrained
  // to the screen; here the popup slides left by the overhang).
  requestAnimationFrame(() => {
    const win = document.getElementById("win");
    if (!pop.isConnected || !win) return;
    const over = pop.getBoundingClientRect().right - (win.getBoundingClientRect().right - 8 * winScale());
    if (over > 0) pop.style.left = -over / winScale() + "px";
  });
  return pop;
}
// A press anywhere but inside the label or its popup closes the list (a
// press on the label itself toggles it in its click). The node goes, not a
// render: a render under a pressed button would replace it before its click.
document.addEventListener("pointerdown", e => {
  if (S.changesPop && !(e.target instanceof Element && e.target.closest(".chfield"))) {
    S.changesPop = false;
    const pop = document.getElementById("changes-popup");
    if (pop) pop.remove();
  }
});
// The kept shortcuts (Ctrl+S, Ctrl+F, Ctrl+I, Ctrl+B); the draft binds them on
// the document. Ctrl+F/Ctrl+I are aesthetics writes: no-ops under the lock;
// Ctrl+B opens Bump all stats on a player row.
function onKey(e) {
  if ((e.ctrlKey || e.metaKey) && S.save) {
    if (e.key === "s") { e.preventDefault(); saveFile(); render(); }
    else if (e.key === "b" && !isTeamSel()) { e.preventDefault(); dlgBumpStats(); }
    else if (e.key === "i" && aesUnlocked()) { e.preventDefault(); fpcToggle(curPlayer()); render(); }
    else if (e.key === "f" && aesUnlocked()) { e.preventDefault(); clearVisualFlags(); }
  }
  if (e.key === "Escape" && S.picker) { closePicker(); render(); }
  if (e.key === "Escape" && S.changesPop) { S.changesPop = false; render(); }
}
// ---- Full Player Customization (spec/libs/fpc.md; SE-GUI-11) ----
// The hide/unhide presets' fields (fpc::preset): the nonexistent ids are the
// suite-common setting's 4cc convention (55/11). SkinColor::Preset resets a
// skin of 7 to 1 and leaves any other (ops/fpc.rs::apply).
const FPC_HIDE = { sleeves: "long", untucked: false, socks: "short", boots_id: 55, gloves_id: 11 };
const FPC_UNHIDE = { sleeves: "short", untucked: true, socks: "standard", boots_id: 0, gloves_id: 0 };
// The save-side classifier (ops/fpc.rs::is_fpc_player): the convention's
// nonexistent boots id, or a custom skin.
const isFpc = p => p.boots_id === 55 || p.appearance.skin_color === 7;
// A model's own boots or gloves ID is kept: a preset's ID replaces only 0 or
// the hide ID (plans/save_editor.md "Full Player Customization (FPC)").
const presetId = (own, hideId, presetValue) => own === 0 || own === hideId ? presetValue : own;
function applyPreset(p, pre) {
  const st = p.appearance.strip;
  st.sleeves = pre.sleeves; st.untucked = pre.untucked; st.socks = pre.socks;
  p.boots_id = presetId(p.boots_id, FPC_HIDE.boots_id, pre.boots_id);
  p.gloves_id = presetId(p.gloves_id, FPC_HIDE.gloves_id, pre.gloves_id);
  if (p.appearance.skin_color === 7) p.appearance.skin_color = 1;
}
function fpcHide(p, on) {
  edit(on ? "Hide default body" : "Show default body", () => applyPreset(p, on ? FPC_HIDE : FPC_UNHIDE));
}
// Ctrl+I: shows a player the classifier reads as hidden, hides any other.
function fpcToggle(p) { fpcHide(p, !isFpc(p)); }
// The interference rules' findings for `p` (fpc::check's fixed order):
// the catalog's own texts.
function fpcFindings(p) {
  const st = p.appearance.strip, fpc = isFpc(p), out = [];
  if (st.inners !== "off" && fpc)
    out.push(["err", "The player wears inners under a hidden body, which breaks the hiding."]);
  if (st.undershorts !== "off" && fpc)
    out.push(["err", "The player wears undershorts under a hidden body, which breaks the hiding."]);
  if ((st.wrist_taping !== "off" || st.ankle_taping) && fpc)
    out.push(["", "The player wears wrist or ankle taping under a hidden body, so the taped pieces still show."]);
  if (st.gloves && p.gloves_id === 0)
    out.push(["warn", "The gloves checkbox is on with gloves ID 0."]);
  if (p.appearance.skin_color === 7 && !fpc)
    out.push(["warn", "A player wears a custom skin, but his body is not hidden by the FPC hide boots ID from Settings, so the skin hides his body but not his jersey."]);
  return out;
}

// ---- The menus: Player, Team, Savefile operations ----
